import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2020-05-21 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2020-05-21 :: Ceph Performance Meeting","date":"2020-05-21T00:00:00.000Z","updated":"2020-05-22T00:00:00.000Z","tags":["Ceph性能","AVX2编码","RocksDB","内存增长","OSD性能"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-05-21_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2020/2020-05-21_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780459816000}'),o={name:"posts/2020/2020-05-21_-_-_Ceph_Performance_Meeting.md"};function r(n,l,s,h,u,c){return a(),i("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>日期与时间</strong>: 会议于2020年5月21日举行。</li><li><strong>参与者</strong>: Adam, Mark, Igor以及其他未明确提及的参与者。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>AVX2编码优化</strong>:</p><ul><li>本周有两个新的Pull Request与AVX2编码相关，针对缓冲列表的编码和解码。</li><li>预计在某些情况下速度提升两倍，其他情况下提升20%。</li></ul></li><li><p><strong>RocksDB数据损坏问题</strong>:</p><ul><li>报告了数据损坏问题，可能与RocksDB更新到6.5.1版本有关。</li><li>正在考虑更新到6.5.1版本，以解决一些已知问题。</li></ul></li><li><p><strong>内存增长问题</strong>:</p><ul><li>用户报告了内存增长问题，特别是在启用压缩的情况下。</li><li>Adam正在进行相关工作，发现对象在预创建但未填充数据时内存使用很小，但一旦填充数据后，内存使用会迅速增长。</li></ul></li><li><p><strong>OSD性能测试</strong>:</p><ul><li>进行了关于在单个设备上运行多个OSD的性能测试。</li><li>结果显示，在某些情况下，单个OSD的性能优于多个OSD。</li></ul></li><li><p><strong>数据损坏与RocksDB</strong>:</p><ul><li>Igor报告了关于RocksDB数据损坏的问题，可能与最近的修改有关，特别是禁用BlueStore缓冲IO和预扩展写头日志的修改。</li><li>正在进一步调查和测试，以确认问题的根本原因。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>继续对AVX2编码优化进行测试和评估。</li><li>考虑更新RocksDB到6.5.1版本，以解决数据损坏问题。</li><li>对内存增长问题进行深入分析，并寻找解决方案。</li><li>继续进行OSD性能测试，并根据结果调整配置和策略。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完成AVX2编码优化的测试，并根据结果决定是否合并Pull Request。</li><li>确认RocksDB数据损坏问题的根本原因，并制定相应的修复措施。</li><li>继续分析内存增长问题，并提出具体的解决方案。</li><li>根据OSD性能测试的结果，优化集群配置和运行策略。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>讨论了CBT（Ceph Benchmarking Tool）的使用和改进，以更好地支持性能测试。</li><li>确认了RocksDB数据损坏问题与特定修改的关系，并计划进行进一步的测试和验证。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><ul><li>会议讨论了多个关键的技术问题，并制定了相应的行动计划。</li><li>感谢所有参与者的贡献，并期待后续的进展和解决方案。</li></ul><p><strong>会议结束语</strong>: 感谢大家的参与，祝大家有一个愉快的一周。</p>',14)])])}const p=e(o,[["render",r]]);export{d as __pageData,p as default};
